/* ─── Reset & Base ─────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg: #f8f7f4;
  --clr-surface: #ffffff;
  --clr-border: #e8e5e0;
  --clr-text: #1a1a1a;
  --clr-muted: #6b6660;
  --clr-accent: #d4521a;
  --clr-accent-dark: #b3421200;
  --clr-accent-light: #fdf0e8;
  --clr-badge: #1a6b45;
  --clr-badge-bg: #e8f5ef;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Georgia', 'Times New Roman', serif;
  --radius: 12px;
  --radius-sm: 6px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.07);
  --shadow-md: 0 4px 16px rgba(0,0,0,.09);
  --shadow-lg: 0 12px 40px rgba(0,0,0,.12);
  --transition: 0.22s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--clr-bg);
  color: var(--clr-text);
  line-height: 1.6;
  font-size: 15px;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* ─── Utilities ────────────────────────────────────────────── */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section-label {
  font-size: 11px; font-weight: 700; letter-spacing: .12em;
  text-transform: uppercase; color: var(--clr-muted);
}
.section-title {
  font-size: clamp(1.5rem, 3vw, 2.1rem);
  font-weight: 700; line-height: 1.2; letter-spacing: -.02em;
}
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 11px 22px; border-radius: 50px;
  font-size: 14px; font-weight: 600;
  transition: background var(--transition), color var(--transition),
              transform var(--transition), box-shadow var(--transition);
  white-space: nowrap;
}
.btn:active { transform: scale(.97); }
.btn-primary { background: var(--clr-text); color: #fff; }
.btn-primary:hover { background: #333; box-shadow: 0 4px 14px rgba(0,0,0,.18); }
.btn-outline {
  background: transparent; color: var(--clr-text);
  border: 1.5px solid var(--clr-border);
}
.btn-outline:hover { border-color: var(--clr-text); background: #f0ede8; }
.btn-accent { background: var(--clr-accent); color: #fff; }
.btn-accent:hover { background: #c04718; box-shadow: 0 4px 14px rgba(212,82,26,.3); }

/* ─── Header ───────────────────────────────────────────────── */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--clr-border);
}
.header-inner {
  display: flex; align-items: center; gap: 24px;
  height: 64px;
}
.logo {
  font-size: 1.25rem; font-weight: 800; letter-spacing: -.04em;
  flex-shrink: 0;
}
.logo span { color: var(--clr-accent); }

.nav { display: flex; align-items: center; gap: 4px; margin-left: 16px; }
.nav a {
  padding: 6px 12px; border-radius: 8px; font-size: 14px; font-weight: 500;
  color: var(--clr-muted); transition: color var(--transition), background var(--transition);
}
.nav a:hover, .nav a.active { color: var(--clr-text); background: #f0ede8; }

.header-search {
  flex: 1; max-width: 340px; margin-left: auto;
  position: relative;
}
.header-search input {
  width: 100%; padding: 9px 16px 9px 40px;
  border: 1.5px solid var(--clr-border); border-radius: 50px;
  background: var(--clr-bg); font-size: 14px; font-family: inherit;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}
.header-search input:focus {
  border-color: var(--clr-text);
  box-shadow: 0 0 0 3px rgba(26,26,26,.07);
}
.header-search .search-icon {
  position: absolute; left: 13px; top: 50%; transform: translateY(-50%);
  color: var(--clr-muted); pointer-events: none;
}

.header-actions { display: flex; align-items: center; gap: 4px; }
.icon-btn {
  width: 40px; height: 40px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--clr-muted); transition: background var(--transition), color var(--transition);
  position: relative;
}
.icon-btn:hover { background: #f0ede8; color: var(--clr-text); }
.cart-count {
  position: absolute; top: 4px; right: 4px;
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--clr-accent); color: #fff;
  font-size: 9px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}

/* ─── Announcement Bar ─────────────────────────────────────── */
.announcement-bar {
  background: var(--clr-text); color: #fff;
  text-align: center; padding: 9px 24px;
  font-size: 13px; font-weight: 500;
  display: flex; align-items: center; justify-content: center; gap: 8px;
}
.announcement-bar a { color: #fff; text-decoration: underline; text-underline-offset: 3px; }

/* ─── Hero ─────────────────────────────────────────────────── */
.hero {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 16px; padding: 24px 0;
  min-height: 520px;
}
.hero-main {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 60%, #0f3460 100%);
  border-radius: var(--radius);
  padding: 56px 52px;
  display: flex; flex-direction: column; justify-content: flex-end;
  position: relative; overflow: hidden;
  min-height: 440px;
}
.hero-main::before {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='400' height='400' viewBox='0 0 400 400' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='300' cy='120' r='180' fill='%23ffffff08'/%3E%3Ccircle cx='350' cy='300' r='100' fill='%23ffffff05'/%3E%3C/svg%3E") center/cover;
}
.hero-eyebrow {
  font-size: 11px; font-weight: 700; letter-spacing: .14em;
  text-transform: uppercase; color: rgba(255,255,255,.55);
  margin-bottom: 12px;
}
.hero-title {
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 800; line-height: 1.1;
  letter-spacing: -.03em; color: #fff;
  margin-bottom: 16px;
}
.hero-title em { font-style: normal; color: #f8c97a; }
.hero-desc {
  color: rgba(255,255,255,.7); font-size: 15px;
  max-width: 340px; margin-bottom: 28px;
}
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }

.hero-side { display: flex; flex-direction: column; gap: 16px; }
.hero-card {
  flex: 1; border-radius: var(--radius); padding: 32px;
  display: flex; flex-direction: column; justify-content: flex-end;
  position: relative; overflow: hidden; min-height: 0;
}
.hero-card-a {
  background: linear-gradient(135deg, #fef3e8 0%, #fde8cc 100%);
}
.hero-card-b {
  background: linear-gradient(135deg, #e8f4fd 0%, #cce8f7 100%);
}
.hero-card-icon {
  font-size: 3rem; position: absolute; right: 20px; top: 16px;
  opacity: .6;
}
.hero-card-label {
  font-size: 11px; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: var(--clr-muted); margin-bottom: 6px;
}
.hero-card-title {
  font-size: 1.15rem; font-weight: 700; margin-bottom: 12px;
  line-height: 1.3;
}
.hero-card-link {
  font-size: 13px; font-weight: 600; color: var(--clr-accent);
  display: flex; align-items: center; gap: 5px;
  transition: gap var(--transition);
}
.hero-card-link:hover { gap: 9px; }

/* ─── Category Chips ───────────────────────────────────────── */
.categories { padding: 32px 0 0; }
.categories-list {
  display: flex; gap: 10px; overflow-x: auto; padding-bottom: 4px;
  scrollbar-width: none;
}
.categories-list::-webkit-scrollbar { display: none; }
.category-chip {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 18px; border-radius: 50px;
  background: var(--clr-surface); border: 1.5px solid var(--clr-border);
  font-size: 13px; font-weight: 600; white-space: nowrap;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}
.category-chip:hover, .category-chip.active {
  background: var(--clr-text); color: #fff; border-color: var(--clr-text);
}
.category-chip .chip-emoji { font-size: 16px; }

/* ─── Section Wrapper ──────────────────────────────────────── */
.section { padding: 56px 0; }
.section-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 32px; gap: 16px;
}
.section-header-left { display: flex; flex-direction: column; gap: 6px; }

/* ─── Product Grid ─────────────────────────────────────────── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}
.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--clr-border);
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex; flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}
.product-img-wrap {
  position: relative;
  background: #f4f2ef;
  aspect-ratio: 4/3;
  overflow: hidden;
  display: flex; align-items: center; justify-content: center;
}
.product-img-wrap .product-emoji {
  font-size: 5rem; line-height: 1;
  transition: transform var(--transition);
}
.product-card:hover .product-emoji { transform: scale(1.1) rotate(-4deg); }

.product-badge {
  position: absolute; top: 10px; left: 10px;
  padding: 4px 10px; border-radius: 50px;
  font-size: 11px; font-weight: 700;
  letter-spacing: .04em;
}
.badge-new { background: var(--clr-text); color: #fff; }
.badge-sale { background: var(--clr-accent); color: #fff; }
.badge-bestseller { background: var(--clr-badge-bg); color: var(--clr-badge); }

.product-wishlist {
  position: absolute; top: 10px; right: 10px;
  width: 32px; height: 32px; border-radius: 50%;
  background: rgba(255,255,255,.85); backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center;
  font-size: 15px; transition: background var(--transition), transform var(--transition);
  opacity: 0; transform: scale(.8);
  transition: opacity var(--transition), transform var(--transition);
}
.product-card:hover .product-wishlist { opacity: 1; transform: scale(1); }
.product-wishlist:hover { background: #fff; }
.product-wishlist.active { color: #e0224f; }

.product-info { padding: 16px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.product-brand { font-size: 11px; font-weight: 600; color: var(--clr-muted); letter-spacing: .06em; text-transform: uppercase; }
.product-name { font-size: 14px; font-weight: 600; line-height: 1.35; }
.product-rating { display: flex; align-items: center; gap: 6px; }
.stars { color: #f5a623; font-size: 12px; letter-spacing: 1px; }
.rating-count { font-size: 12px; color: var(--clr-muted); }
.product-price { display: flex; align-items: center; gap: 8px; margin-top: auto; padding-top: 4px; }
.price-current { font-size: 1rem; font-weight: 700; }
.price-original { font-size: 13px; color: var(--clr-muted); text-decoration: line-through; }
.price-save { font-size: 11px; font-weight: 700; color: var(--clr-accent); }
.add-to-cart {
  margin: 0 16px 16px;
  width: calc(100% - 32px);
  padding: 10px; border-radius: 8px;
  background: var(--clr-text); color: #fff;
  font-size: 13px; font-weight: 600;
  transition: background var(--transition), transform var(--transition);
  opacity: 0; transform: translateY(6px);
  transition: opacity var(--transition), transform var(--transition), background var(--transition);
}
.product-card:hover .add-to-cart { opacity: 1; transform: translateY(0); }
.add-to-cart:hover { background: #333; }
.add-to-cart.added { background: var(--clr-badge); }

/* ─── Deals Banner ─────────────────────────────────────────── */
.deals-section { padding: 56px 0; }
.deals-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 32px; flex-wrap: wrap; gap: 16px;
}
.countdown {
  display: flex; align-items: center; gap: 10px;
}
.countdown-label { font-size: 13px; font-weight: 600; color: var(--clr-muted); }
.countdown-timer { display: flex; gap: 6px; }
.countdown-unit {
  background: var(--clr-text); color: #fff;
  border-radius: 6px; padding: 6px 10px;
  text-align: center; min-width: 44px;
}
.countdown-unit .num { font-size: 18px; font-weight: 800; display: block; line-height: 1; }
.countdown-unit .lbl { font-size: 9px; font-weight: 600; opacity: .6; letter-spacing: .06em; text-transform: uppercase; }
.countdown-sep { font-size: 18px; font-weight: 800; align-self: flex-start; margin-top: 6px; }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 20px;
}
.deal-card {
  background: var(--clr-surface);
  border-radius: var(--radius);
  border: 1px solid var(--clr-border);
  overflow: hidden;
  display: flex;
  transition: box-shadow var(--transition), transform var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
.deal-card-img {
  width: 120px; flex-shrink: 0;
  background: #f4f2ef;
  display: flex; align-items: center; justify-content: center;
  font-size: 3.5rem;
}
.deal-card-body { padding: 18px 16px; flex: 1; display: flex; flex-direction: column; gap: 6px; }
.deal-percent {
  font-size: 11px; font-weight: 700; color: var(--clr-accent);
  letter-spacing: .06em; text-transform: uppercase;
}
.deal-name { font-size: 14px; font-weight: 600; line-height: 1.35; }
.deal-price { display: flex; align-items: center; gap: 8px; }
.deal-price .price-current { font-size: 1.1rem; }
.deal-progress-wrap { margin-top: auto; }
.deal-progress-label { font-size: 11px; color: var(--clr-muted); margin-bottom: 5px; }
.deal-progress { height: 4px; background: #eee; border-radius: 2px; overflow: hidden; }
.deal-progress-fill { height: 100%; background: var(--clr-accent); border-radius: 2px; transition: width 1s ease; }

/* ─── Editorial / Content Grid ─────────────────────────────── */
.editorial-section { padding: 56px 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}
.editorial-card {
  background: var(--clr-surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--clr-border);
  transition: box-shadow var(--transition);
  cursor: pointer;
}
.editorial-card:hover { box-shadow: var(--shadow-md); }
.editorial-card.featured { grid-row: span 2; }
.editorial-img {
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, #e8e0f4 0%, #d4c8f0 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 5rem; position: relative; overflow: hidden;
}
.editorial-card.featured .editorial-img { aspect-ratio: 3/4; font-size: 7rem; }
.editorial-img-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.3) 0%, transparent 50%);
}
.editorial-body { padding: 20px; }
.editorial-tag {
  display: inline-block;
  padding: 3px 10px; border-radius: 50px;
  font-size: 10px; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
  margin-bottom: 10px;
}
.tag-style { background: #f0e8ff; color: #6b3fd4; }
.tag-living { background: #e8f5e9; color: #2e7d32; }
.tag-tech { background: #e3f2fd; color: #1565c0; }
.tag-wellness { background: #fce4ec; color: #c62828; }
.editorial-card-title {
  font-family: var(--font-serif); font-size: 1.05rem;
  font-weight: 700; line-height: 1.35;
  margin-bottom: 8px;
}
.editorial-card.featured .editorial-card-title { font-size: 1.3rem; }
.editorial-card-excerpt { font-size: 13px; color: var(--clr-muted); line-height: 1.6; }
.editorial-meta { display: flex; align-items: center; gap: 8px; margin-top: 14px; }
.editorial-avatar {
  width: 28px; height: 28px; border-radius: 50%;
  background: #e0dbd4; display: flex; align-items: center; justify-content: center;
  font-size: 12px;
}
.editorial-byline { font-size: 12px; color: var(--clr-muted); }
.editorial-byline strong { color: var(--clr-text); font-weight: 600; }

/* ─── Brands Bar ───────────────────────────────────────────── */
.brands-section { padding: 40px 0; border-top: 1px solid var(--clr-border); }
.brands-label { text-align: center; margin-bottom: 24px; }
.brands-list {
  display: flex; align-items: center; justify-content: center;
  gap: 40px; flex-wrap: wrap;
}
.brand-item {
  font-size: 1rem; font-weight: 800; letter-spacing: -.03em;
  color: #ccc; text-transform: uppercase; letter-spacing: .12em;
  font-size: .85rem;
  transition: color var(--transition);
}
.brand-item:hover { color: var(--clr-text); }

/* ─── Newsletter ───────────────────────────────────────────── */
.newsletter-section {
  padding: 64px 0;
  background: var(--clr-text);
  color: #fff;
  text-align: center;
}
.newsletter-inner { max-width: 540px; margin: 0 auto; }
.newsletter-label { color: rgba(255,255,255,.5); margin-bottom: 10px; }
.newsletter-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 800; letter-spacing: -.03em;
  margin-bottom: 10px;
}
.newsletter-desc { color: rgba(255,255,255,.6); font-size: 15px; margin-bottom: 28px; }
.newsletter-form { display: flex; gap: 10px; max-width: 420px; margin: 0 auto; }
.newsletter-form input {
  flex: 1; padding: 13px 18px;
  border: 1.5px solid rgba(255,255,255,.15);
  border-radius: 50px;
  background: rgba(255,255,255,.07); color: #fff;
  font-size: 14px; font-family: inherit;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,.35); }
.newsletter-form input:focus { border-color: rgba(255,255,255,.4); }
.newsletter-form .btn-accent { flex-shrink: 0; }

/* ─── Footer ───────────────────────────────────────────────── */
.site-footer {
  border-top: 1px solid var(--clr-border);
  padding: 48px 0 28px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 40px;
}
.footer-brand .logo { font-size: 1.1rem; margin-bottom: 12px; }
.footer-desc { font-size: 13px; color: var(--clr-muted); line-height: 1.7; max-width: 220px; }
.footer-socials { display: flex; gap: 8px; margin-top: 16px; }
.social-btn {
  width: 36px; height: 36px; border-radius: 50%;
  background: #f0ede8; color: var(--clr-muted);
  display: flex; align-items: center; justify-content: center;
  font-size: 15px; transition: background var(--transition), color var(--transition);
