*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg: #f8f7f4;
  --clr-surface: #ffffff;
  --clr-border: #e8e5e0;
  --clr-text: #1a1a1a;
  --clr-muted: #6b6660;
