}
function closeCart() {
  document.getElementById('cart-drawer').classList.remove('open');
  document.getElementById('cart-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ── Countdown Timer ───────────────────────────────────────────
function startCountdown() {
  const end = Date.now() + (5 * 60 * 60 * 1000) + (23 * 60 * 1000) + (44 * 1000);
  function tick() {
    const diff = Math.max(0, end - Date.now());
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    const pad = n => String(n).padStart(2, '0');
    const el = document.getElementById('countdown');
    if (el) {
      el.querySelector('[data-unit="h"] .num').textContent = pad(h);
      el.querySelector('[data-unit="m"] .num').textContent = pad(m);
      el.querySelector('[data-unit="s"] .num').textContent = pad(s);
    }
  }
  tick();
  setInterval(tick, 1000);
}

// ── Wishlist ──────────────────────────────────────────────────
function toggleWishlist(id) {
  const btn = document.querySelector(`[data-wishlist="${id}"]`);
  if (!btn) return;
  if (wishlist.has(id)) {
    wishlist.delete(id);
    btn.textContent = '♡';
    btn.classList.remove('active');
    showToast('Removed from wishlist');
  } else {
    wishlist.add(id);
    btn.textContent = '♥';
    btn.classList.add('active');
    showToast('Added to wishlist');
  }
}

// ── Category Filter ───────────────────────────────────────────
function initCategories() {
  document.querySelectorAll('.category-chip').forEach(chip => {
    chip.addEventListener('click', function() {
      document.querySelectorAll('.category-chip').forEach(c => c.classList.remove('active'));
      this.classList.add('active');
    });
  });
}

// ── Event Delegation ──────────────────────────────────────────
function bindEvents() {
  // Product card clicks
  document.getElementById('products-grid').addEventListener('click', e => {
    const addBtn = e.target.closest('.add-to-cart');
    if (addBtn) {
      const id = Number(addBtn.dataset.id);
      const product = PRODUCTS.find(p => p.id === id);
      if (product) {
        addBtn.textContent = '✓ Added';
        addBtn.classList.add('added');
        setTimeout(() => { addBtn.textContent = 'Add to Cart'; addBtn.classList.remove('added'); }, 1500);
        addToCart(product);
      }
    }
    const wishBtn = e.target.closest('.product-wishlist');
    if (wishBtn) {
      e.stopPropagation();
      toggleWishlist(Number(wishBtn.dataset.wishlist));
    }
  });

  // Deal card add
  document.getElementById('deals-grid').addEventListener('click', e => {
    const card = e.target.closest('.deal-card');
    if (card) {
      const id = Number(card.dataset.id);
      const deal = DEALS.find(d => d.id === id);
      if (deal) addToCart({ id: deal.id + 100, name: deal.name, price: deal.price, emoji: deal.emoji });
    }
  });

  // Cart open
  document.querySelectorAll('[data-open-cart]').forEach(btn => btn.addEventListener('click', openCart));
  document.getElementById('cart-overlay').addEventListener('click', closeCart);
  document.getElementById('cart-close').addEventListener('click', closeCart);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') closeCart(); });

  // Cart remove
  document.getElementById('cart-items').addEventListener('click', e => {
    const removeBtn = e.target.closest('[data-remove]');
    if (removeBtn) removeFromCart(Number(removeBtn.dataset.remove));
  });

  // Newsletter
  const form = document.getElementById('newsletter-form');
  form.addEventListener('submit', e => {
    e.preventDefault();
    const input = form.querySelector('input[type="email"]');
    if (input.value) {
      showToast('You\'re subscribed! Welcome 🎉');
      input.value = '';
    }
  });
}

// ── Intersection Observer for scroll animations ───────────────
function initScrollReveal() {
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.style.opacity = '1';
        entry.target.style.transform = 'translateY(0)';
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });

  document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach((el, i) => {
    el.style.opacity = '0';
    el.style.transform = 'translateY(24px)';
    el.style.transition = `opacity .45s ease ${i * 0.06}s, transform .45s ease ${i * 0.06}s, box-shadow .22s, border-color .22s`;
    observer.observe(el);
  });
}

// ── Init ──────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  renderProducts();
  renderDeals();
  renderEditorial();
  updateCartUI();
  startCountdown();
  initCategories();
  bindEvents();
  setTimeout(initScrollReveal, 50);
});
