// ── Helpers ───────────────────────────────────────────────────
function fmt(price) { return `$${price.toFixed(0)}`; }
function stars(rating) { return '★'.repeat(Math.round(rating)) + '☆'.repeat(5 - Math.round(rating)); }
function storeCart() { try { localStorage.setItem('cart', JSON.stringify(cart)); } catch(e) {} }

function showToast(msg) {
  const container = document.getElementById('toast-container');
  const t = document.createElement('div');
  t.className = 'toast';
  t.innerHTML = `<span>✓</span> ${msg}`;
  container.appendChild(t);
  requestAnimationFrame(() => { requestAnimationFrame(() => { t.classList.add('show'); }); });
  setTimeout(() => {
    t.classList.remove('show');
    setTimeout(() => t.remove(), 300);
  }, 2500);
}

// ── Render Products ───────────────────────────────────────────
function renderProducts() {
  const grid = document.getElementById('products-grid');
  grid.innerHTML = PRODUCTS.map(p => {
    const hasDiscount = p.original !== null;
    const badgeHtml = p.badge
      ? `<span class="product-badge badge-${p.badge}">${p.badge === 'bestseller' ? 'Best Seller' : p.badge.charAt(0).toUpperCase() + p.badge.slice(1)}</span>`
      : '';
    return `
      <article class="product-card" data-id="${p.id}">
        <div class="product-img-wrap">
          ${badgeHtml}
          <span class="product-emoji">${p.emoji}</span>
          <button class="product-wishlist" aria-label="Wishlist" data-wishlist="${p.id}">♡</button>
        </div>
        <div class="product-info">
          <span class="product-brand">${p.brand}</span>
          <h3 class="product-name">${p.name}</h3>
          <div class="product-rating">
            <span class="stars">${stars(p.rating)}</span>
            <span class="rating-count">(${p.reviews.toLocaleString()})</span>
          </div>
          <div class="product-price">
            <span class="price-current">${fmt(p.price)}</span>
            ${hasDiscount ? `<span class="price-original">${fmt(p.original)}</span>` : ''}
            ${hasDiscount ? `<span class="price-save">Save ${fmt(p.original - p.price)}</span>` : ''}
          </div>
        </div>
        <button class="add-to-cart" data-id="${p.id}">Add to Cart</button>
      </article>`;
  }).join('');
}

// ── Render Deals ──────────────────────────────────────────────
function renderDeals() {
  const grid = document.getElementById('deals-grid');
  grid.innerHTML = DEALS.map(d => `
    <article class="deal-card" data-id="${d.id}">
      <div class="deal-card-img">${d.emoji}</div>
      <div class="deal-card-body">
        <span class="deal-percent">−${d.percent}% OFF</span>
        <h3 class="deal-name">${d.name}</h3>
        <div class="deal-price">
          <span class="price-current">${fmt(d.price)}</span>
          <span class="price-original">${fmt(d.original)}</span>
        </div>
        <div class="deal-progress-wrap">
          <p class="deal-progress-label">${d.sold}% claimed</p>
          <div class="deal-progress">
            <div class="deal-progress-fill" style="width:0%" data-target="${d.sold}"></div>
          </div>
        </div>
      </div>
    </article>`
