+];
+
+const DEALS = [
+  { id: 1, name: 'Leather Weekend Bag', brand: 'Ashford', price: 189, original: 320, percent: 41, emoji: '💼', sold: 74 },
+  { id: 2, name: 'Silk Blend Blouse', brand: 'Maison Clair', price: 55, original: 95, percent: 42, emoji: '👘', sold: 58 },
+  { id: 3, name: 'Suede Chelsea Boots', brand: 'Rivière', price: 165, original: 249, percent: 34, emoji: '🥾', sold: 87 },
