+  { id: 6, name: 'Hand-Knit Beanie', brand: 'Nordvik', price: 32, original: 52, percent: 38, emoji: '🎩', sold: 45 },
+];
+
+const EDITORIAL = [
+  {
+    id: 1, featured: true,
+    tag: 'Style', tagClass: 'tag-style',
+    title: 'The Art of Effortless Dressing: Building a Wardrobe That Works for You',
+    excerpt: 'Discover how thoughtful curation of a few key pieces can transform your mornings and elevate every outfit you wear — from desk to dinner.',
+    author: 'Sophie Laurent', authorEmoji: '👩', date: 'Apr 28',
+    imgColor: 'linear-gradient(135deg,#f0e6ff 0%,#d4b8f7 100%)', imgEmoji: '✨',
+  },
+  {
+    id: 2, featured: false,
+    tag: 'Living', tagClass: 'tag-living',
+    title: 'Spring Home Refresh: The Pieces Worth Investing In',
+    excerpt: 'From textured throws to artisan ceramics, these are the items that make a space feel truly yours.',
+    author: 'Marco Chen', authorEmoji: '👨', date: 'Apr 24',
+    imgColor: 'linear-gradient(135deg,#e8f5e9 0%,#c8e6c9 100%)', imgEmoji: '🌿',
+  },
+  {
+    id: 3, featured: false,
+    tag: 'Tech', tagClass: 'tag-tech',
+    title: 'Smart Accessories: Where Form Meets Function',
+    excerpt: 'The best tech accessories don\'t just work well — they look great doing it.',
+    author: 'Aisha Brooks', authorEmoji: '🧑', date: 'Apr 20',
+    imgColor: 'linear-gradient(135deg,#e3f2fd 0%,#bbdefb 100%)', imgEmoji: '⌚',
+  },
+];
+
+// ── State ─────────────────────────────────────────────────────
+let cart = [];
+let wishlist = new Set();
+
+// ── Helpers ───────────────────────────────────────────────────
+function fmt(price) { return `$${price.toFixed(0)}`; }
+function stars(rating) { return '★'.repeat(Math.round(rating)) + '☆'.repeat(5 - Math.round(rating)); }
+function storeCart() { try { localStorage.setItem('cart', JSON.stringify(cart)); } catch(e) {} }
+
+function showToast(msg) {
+  const container = document.getElementById('toast-container');
+  const t = document.createElement('div');
+  t.className = 'toast';
+  t.innerHTML = `<span>✓</span> ${msg}`;
+  container.appendChild(t);
+  requestAnimationFrame(() => { requestAnimationFrame(() => { t.classList.add('show'); }); });
+  setTimeout(() => {
+    t.classList.remove('show');
+    setTimeout(() => t.remove(), 300);
+  }, 2500);
+}
+
+// ── Render Products ───────────────────────────────────────────
+function renderProducts() {
+  const grid = document.getElementById('products-grid');
+  grid.innerHTML = PRODUCTS.map(p => {
+    const hasDiscount = p.original !== null;
+    const badgeHtml = p.badge
+      ? `<span class="product-badge badge-${p.badge}">${p.badge === 'bestseller' ? 'Best Seller' : p.badge.charAt(0).toUpperCase() + p.badge.slice(1)}</span>`
+      : '';
+    return `
+      <article class="product-card" data-id="${p.id}">
+        <div class="product-img-wrap">
+          ${badgeHtml}
+          <span class="product-emoji">${p.emoji}</span>
+          <button class="product-wishlist" aria-label="Wishlist" data-wishlist="${p.id}">♡</button>
+        </div>
+        <div class="product-info">
+          <span class="product-brand">${p.brand}</span>
+          <h3 class="product-name">${p.name}</h3>
+          <div class="product-rating">
+            <span class="stars">${stars(p.rating)}</span>
+            <span class="rating-count">(${p.reviews.toLocaleString()})</span>
+          </div>
+          <div class="product-price">
+            <span class="price-current">${fmt(p.price)}</span>
+            ${hasDiscount ? `<span class="price-original">${fmt(p.original)}</span>` : ''}
+            ${hasDiscount ? `<span class="price-save">Save ${fmt(p.original - p.price)}</span>` : ''}
+          </div>
+        </div>
+        <button class="add-to-cart" data-id="${p.id}">Add to Cart</button>
+      </article>`;
+  }).join('');
+}
+
+// ── Render Deals ──────────────────────────────────────────────
+function renderDeals() {
+  const grid = document.getElementById('deals-grid');
+  grid.innerHTML = DEALS.map(d => `
+    <article class="deal-card" data-id="${d.id}">
+      <div class="deal-card-img">${d.emoji}</div>
+      <div class="deal-card-body">
+        <span class="deal-percent">−${d.percent}% OFF</span>
+        <h3 class="deal-name">${d.name}</h3>
+        <div class="deal-price">
+          <span class="price-current">${fmt(d.price)}</span>
+          <span class="price-original">${fmt(d.original)}</span>
+        </div>
+        <div class="deal-progress-wrap">
+          <p class="deal-progress-label">${d.sold}% claimed</p>
+          <div class="deal-progress">
+            <div class="deal-progress-fill" style="width:0%" data-target="${d.sold}"></div>
+          </div>
+        </div>
+      </div>
+    </article>`
+  ).join('');
+
+  // Animate progress bars
+  setTimeout(() => {
+    document.querySelectorAll('.deal-progress-fill').forEach(bar => {
+      bar.style.width = bar.dataset.target + '%';
+    });
+  }, 400);
+}
+
+// ── Render Editorial ──────────────────────────────────────────
+function renderEditorial() {
+  const grid = document.getElementById('editorial-grid');
+  grid.innerHTML = EDITORIAL.map(e => `
+    <article class="editorial-card ${e.featured ? 'featured' : ''}" tabindex="0">
+      <div class="editorial-img" style="background:${e.imgColor}">
+        <span>${e.imgEmoji}</span>
+        <div class="editorial-img-overlay"></div>
+      </div>
+      <div class="editorial-body">
+        <span class="editorial-tag ${e.tagClass}">${e.tag}</span>
+        <h3 class="editorial-card-title">${e.title}</h3>
+        ${e.featured || !e.featured ? `<p class="editorial-card-excerpt">${e.excerpt}</p>` : ''}
+        <div class="editorial-meta">
+          <div class="editorial-avatar">${e.authorEmoji}</div>
+          <span class="editorial-byline"><strong>${e.author}</strong> · ${e.date}</span>
+        </div>
+      </div>
+    </article>`
+  ).join('');
+}
+
+// ── Cart ──────────────────────────────────────────────────────
+function addToCart(product) {
+  const existing = cart.find(i => i.id === product.id);
+  if (existing) { existing.qty++; }
+  else { cart.push({ ...product, qty: 1 }); }
+  storeCart();
+  updateCartUI();
+  showToast(`${product.name} added to cart`);
+}
+
+function removeFromCart(id) {
+  cart = cart.filter(i => i.id !== id);
+  storeCart();
+  updateCartUI();
+}
+
+function updateCartUI() {
+  const count = cart.reduce((s, i) => s + i.qty, 0);
+  const total = cart.reduce((s, i) => s + i.price * i.qty, 0);
+
+  document.querySelectorAll('.cart-count').forEach(el => {
+    el.textContent = count;
+    el.style.display = count ? '' : 'none';
+  });
+  document.querySelector('.total-amount').textContent = fmt(total);
+
+  const itemsContainer = document.getElementById('cart-items');
+  if (cart.length === 0) {
+    itemsContainer.innerHTML = `<div class="cart-empty"><div class="empty-icon">🛍️</div><p>Your cart is empty</p></div>`;
+  } else {
+    itemsContainer.innerHTML = cart.map(item => `
+      <div class="cart-item">
+        <div class="cart-item-img">${item.emoji}</div>
+        <div class="cart-item-info">
+          <p class="cart-item-name">${item.name}${item.qty > 1 ? ` ×${item.qty}` : ''}</p>
+          <p class="cart-item-price">${fmt(item.price * item.qty)}</p>
+        </div>
+        <button class="cart-item-remove icon-btn" data-remove="${item.id}" aria-label="Remove">×</button>
+      </div>`
+    ).join('');
+  }
+}
+
+function openCart() {
+  document.getElementById('cart-drawer').classList.add('open');
+  document.getElementById('cart-overlay').classList.add('open');
+  document.body.style.overflow = 'hidden';
+}
+function closeCart() {
+  document.getElementById('cart-drawer').classList.remove('open');
+  document.getElementById('cart-overlay').classList.remove('open');
+  document.body.style.overflow = '';
+}
+
+// ── Countdown Timer ───────────────────────────────────────────
+function startCountdown() {
+  const end = Date.now() + (5 * 60 * 60 * 1000) + (23 * 60 * 1000) + (44 * 1000);
+  function tick() {
+    const diff = Math.max(0, end - Date.now());
+    const h = Math.floor(diff / 3600000);
+    const m = Math.floor((diff % 3600000) / 60000);
+    const s = Math.floor((diff % 60000) / 1000);
+    const pad = n => String(n).padStart(2, '0');
+    const el = document.getElementById('countdown');
+    if (el) {
+      el.querySelector('[data-unit="h"] .num').textContent = pad(h);
+      el.querySelector('[data-unit="m"] .num').textContent = pad(m);
+      el.querySelector('[data-unit="s"] .num').textContent = pad(s);
+    }
+  }
+  tick();
+  setInterval(tick, 1000);
+}
+
+// ── Wishlist ──────────────────────────────────────────────────
+function toggleWishlist(id) {
+  const btn = document.querySelector(`[data-wishlist="${id}"]`);
+  if (!btn) return;
+  if (wishlist.has(id)) {
+    wishlist.delete(id);
+    btn.textContent = '♡';
+    btn.classList.remove('active');
+    showToast('Removed from wishlist');
+  } else {
+    wishlist.add(id);
+    btn.textContent = '♥';
+    btn.classList.add('active');
+    showToast('Added to wishlist');
+  }
+}
+
+// ── Category Filter ───────────────────────────────────────────
+function initCategories() {
+  document.querySelectorAll('.category-chip').forEach(chip => {
+    chip.addEventListener('click', function() {
+      document.querySelectorAll('.category-chip').forEach(c => c.classList.remove('active'));
+      this.classList.add('active');
+    });
+  });
+}
+
+// ── Event Delegation ──────────────────────────────────────────
+function bindEvents() {
+  // Product card clicks
+  document.getElementById('products-grid').addEventListener('click', e => {
+    const addBtn = e.target.closest('.add-to-cart');
+    if (addBtn) {
+      const id = Number(addBtn.dataset.id);
+      const product = PRODUCTS.find(p => p.id === id);
+      if (product) {
+        addBtn.textContent = '✓ Added';
+        addBtn.classList.add('added');
+        setTimeout(() => { addBtn.textContent = 'Add to Cart'; addBtn.classList.remove('added'); }, 1500);
+        addToCart(product);
+      }
+    }
+    const wishBtn = e.target.closest('.product-wishlist');
+    if (wishBtn) {
+      e.stopPropagation();
+      toggleWishlist(Number(wishBtn.dataset.wishlist));
+    }
+  });
+
+  // Deal card add
+  document.getElementById('deals-grid').addEventListener('click', e => {
+    const card = e.target.closest('.deal-card');
+    if (card) {
+      const id = Number(card.dataset.id);
+      const deal = DEALS.find(d => d.id === id);
+      if (deal) addToCart({ id: deal.id + 100, name: deal.name, price: deal.price, emoji: deal.emoji });
+    }
+  });
+
+  // Cart open
+  document.querySelectorAll('[data-open-cart]').forEach(btn => btn.addEventListener('click', openCart));
+  document.getElementById('cart-overlay').addEventListener('click', closeCart);
+  document.getElementById('cart-close').addEventListener('click', closeCart);
+  document.addEventListener('keydown', e => { if (e.key === 'Escape') closeCart(); });
+
+  // Cart remove
+  document.getElementById('cart-items').addEventListener('click', e => {
+    const removeBtn = e.target.closest('[data-remove]');
+    if (removeBtn) removeFromCart(Number(removeBtn.dataset.remove));
+  });
+
+  // Newsletter
+  const form = document.getElementById('newsletter-form');
+  form.addEventListener('submit', e => {
+    e.preventDefault();
+    const input = form.querySelector('input[type="email"]');
+    if (input.value) {
+      showToast('You\'re subscribed! Welcome 🎉');
+      input.value = '';
+    }
+  });
+}
+
+// ── Intersection Observer for scroll animations ───────────────
+function initScrollReveal() {
+  const observer = new IntersectionObserver((entries) => {
+    entries.forEach(entry => {
+      if (entry.isIntersecting) {
+        entry.target.style.opacity = '1';
+        entry.target.style.transform = 'translateY(0)';
+        observer.unobserve(entry.target);
+      }
+    });
+  }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });
+
+  document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach((el, i) => {
+    el.style.opacity = '0';
+    el.style.transform = 'translateY(24px)';
+    el.style.transition = `opacity .45s ease ${i * 0.06}s, transform .45s ease ${i * 0.06}s, box-shadow .22s, border-color .22s`;
+    observer.observe(el);
+  });
+}
+
+// ── Init ──────────────────────────────────────────────────────
+document.addEventListener('DOMContentLoaded', () => {
+  renderProducts();
+  renderDeals();
+  renderEditorial();
+  updateCartUI();
+  startCountdown();
+  initCategories();
+  bindEvents();
+  setTimeout(initScrollReveal, 50);
+});
+
')

